import{_ as t,o as n,c as a,a2 as i}from"./chunks/framework.Buc7gXeZ.js";const p=JSON.parse('{"title":"Space-Einstellungen","description":"Tarif, Sitzplätze, Space-Kennung und weitere Einstellungen eines Space.","frontmatter":{"title":"Space-Einstellungen","description":"Tarif, Sitzplätze, Space-Kennung und weitere Einstellungen eines Space."},"headers":[],"relativePath":"spaces/einstellungen.md","filePath":"spaces/einstellungen.md","lastUpdated":1786092153000}'),r={name:"spaces/einstellungen.md"};function s(l,e,d,o,h,c){return n(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="space-einstellungen" tabindex="-1">Space-Einstellungen <a class="header-anchor" href="#space-einstellungen" aria-label="Permalink to &quot;Space-Einstellungen&quot;">​</a></h1><p>Erreichbar über <strong>Space Einstellungen</strong>. Der Bereich gliedert sich in drei Seiten: <strong>Allgemein</strong>, <strong>Webhooks</strong> und <strong>Links</strong>.</p><div class="tip custom-block"><p class="custom-block-title">Nicht mit den Konto-Einstellungen verwechseln</p><p><strong>Space Einstellungen</strong> gelten für <em>einen Space</em>. <strong>Profil &amp; Einstellungen</strong> gelten für <em>Sie persönlich</em> — dort liegen Profil, Abrechnung und API-Zugangsdaten.</p><p>Eine häufige Verwechslung: Der Tarif wird je Space gebucht, die Zahlungsdaten hängen aber am Konto.</p></div><h2 id="allgemein" tabindex="-1">Allgemein <a class="header-anchor" href="#allgemein" aria-label="Permalink to &quot;Allgemein&quot;">​</a></h2><p>Beschrieben als <em>Allgemeine Einstellungen zu diesem Space</em>.</p><h3 id="tarif" tabindex="-1">Tarif <a class="header-anchor" href="#tarif" aria-label="Permalink to &quot;Tarif&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Angabe</th><th>Bedeutung</th></tr></thead><tbody><tr><td><strong>Dieser Space ist im Plan</strong></td><td>Der aktuelle Tarif</td></tr><tr><td><strong>Plan und Abonnement anpassen</strong></td><td>Führt zur Tarifänderung</td></tr></tbody></table><p>Der Hinweis darunter ist wichtig: <em>Der Eigentümer kann den Plan anpassen.</em> Andere Rollen sehen die Angabe, können sie aber nicht ändern.</p><h3 id="sitzplatze" tabindex="-1">Sitzplätze <a class="header-anchor" href="#sitzplatze" aria-label="Permalink to &quot;Sitzplätze&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Angabe</th><th>Bedeutung</th></tr></thead><tbody><tr><td><strong>Verfügbare Plätze für NutzerInnen mit Bearbeitungsrechten</strong></td><td>Anzahl der Lizenzen</td></tr><tr><td><strong>Plätze anpassen</strong></td><td>Ändert die Anzahl</td></tr></tbody></table><blockquote><p><em>Der Eigentümer kann zusätzliche Plätze für NutzerInnen mit Bearbeitungsrechten erwerben. Leserechte sind kostenfrei.</em></p></blockquote><p>→ <a href="/docs/zusammenarbeit/sitzplaetze">Sitzplätze</a></p><h3 id="testphase" tabindex="-1">Testphase <a class="header-anchor" href="#testphase" aria-label="Permalink to &quot;Testphase&quot;">​</a></h3><p><strong>Test-Phase verbleibende Tage</strong> zeigt die restliche Laufzeit.</p><div class="warning custom-block"><p class="custom-block-title">Vor Ablauf prüfen, was Sie nutzen</p><p>Nach der Testphase gelten die Grenzen des gebuchten Tarifs. Kostenpflichtige Einstellungen — besonders an Formularen — können dabei entfallen.</p><p>Notieren Sie vorher, welche Funktionen Sie produktiv einsetzen.</p></div><h3 id="info" tabindex="-1">Info <a class="header-anchor" href="#info" aria-label="Permalink to &quot;Info&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Angabe</th><th>Bedeutung</th></tr></thead><tbody><tr><td><strong>Space Identifikator</strong></td><td>Technische Kennung des Space</td></tr><tr><td><strong>Erstellt am</strong></td><td>Anlagedatum</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Wofür die Kennung gut ist</p><p>Der Space Identifikator identifiziert den Space eindeutig — nützlich bei Supportanfragen und bei der Arbeit mit der <a href="/docs/integrationen/api-zugangsdaten">Programmierschnittstelle</a>. Für die tägliche Arbeit brauchen Sie ihn nicht.</p></div><p>Zusätzlich erscheint die <strong>Deployment Edition</strong> (<em>Stable</em> oder <em>Enterprise</em>). Was die Editionen unterscheidet, ist in der Anwendung nicht erläutert; bei Bedarf fragen Sie über den Chat nach.</p><h3 id="navigation" tabindex="-1">Navigation <a class="header-anchor" href="#navigation" aria-label="Permalink to &quot;Navigation&quot;">​</a></h3><p>Reihenfolge der Abschnitte und Anzahl sichtbarer Grids.</p><p>→ <a href="/docs/spaces/navigation">Navigation einrichten</a></p><h2 id="webhooks" tabindex="-1">Webhooks <a class="header-anchor" href="#webhooks" aria-label="Permalink to &quot;Webhooks&quot;">​</a></h2><p>Ausgehende Benachrichtigungen an fremde Systeme, ausgelöst durch Ereignisse in einem Grid.</p><p>Die Anzahl je Space ist tarifabhängig.</p><p>→ <a href="/docs/integrationen/webhooks">Webhooks</a></p><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;Links&quot;">​</a></h2><p>Übersicht <strong>aller</strong> externen Links dieses Space:</p><blockquote><p><em>Hier ist eine Liste aller externen Links in diesem Space</em></p></blockquote><p>Enthalten sind Formularlinks, Ansichtslinks, Portale, Flow-Starts und Einladungen.</p><div class="tip custom-block"><p class="custom-block-title">Die wichtigste Seite für den Überblick</p><p>Dies ist die einzige Stelle, an der alle nach außen offenen Zugänge eines Space gesammelt sichtbar sind. Sehen Sie sie regelmäßig durch — besonders nach abgeschlossenen Projekten, ausgelaufenen Kampagnen und Personalwechseln.</p></div><p>→ <a href="/docs/zusammenarbeit/externe-links">Externe Links im Überblick</a></p><h2 id="wer-was-andern-darf" tabindex="-1">Wer was ändern darf <a class="header-anchor" href="#wer-was-andern-darf" aria-label="Permalink to &quot;Wer was ändern darf&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Einstellung</th><th>Erforderlich</th></tr></thead><tbody><tr><td>Navigation, Webhooks, Links</td><td>Rolle <strong>Managen</strong></td></tr><tr><td>Tarif und Sitzplätze</td><td><strong>Eigentümer</strong></td></tr><tr><td>Ansehen der Angaben</td><td>jede Rolle</td></tr></tbody></table><p>Fehlt Ihnen eine Schaltfläche, prüfen Sie zuerst Ihre Rolle. → <a href="/docs/fehlerbehebung/fehlende-schaltflaechen">Ich sehe eine Schaltfläche nicht</a></p><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/docs/spaces/navigation">Navigation einrichten</a></li><li><a href="/docs/zusammenarbeit/sitzplaetze">Sitzplätze</a></li><li><a href="/docs/spaces/space-loeschen">Space löschen</a></li></ul>',37)])])}const u=t(r,[["render",s]]);export{p as __pageData,u as default};
